+    @Override
+    public void initialize(Properties properties) {
+        boolean configuredStoreCreationAllowed = Boolean.parseBoolean(
+                properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        boolean configuredStoreUpdateAllowed = Boolean.parseBoolean(
+                properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        IntegrityMode configuredIntegrityMode = parseIntegrity(properties);
+        FileNameConfiguration configuredFileNames = parseFileNames(properties);
+        if (configuredIntegrityMode == IntegrityMode.REPAIR && !configuredStoreUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires configuration %s.%s=true",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        File configuredFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
+        File configuredStoredRulesFile = new File(configuredFolder, STORED_RULES_FILE_NAME);
+        FileSyncedProperties configuredStoredRules = getOrCreateStoredRules(configuredStoredRulesFile);
+
+        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), configuredStoredRulesFile.getAbsolutePath());
+        synchronized (configuredStoredRules) {
+            boolean indexExists = existsWithoutFollowingLinks(configuredStoredRulesFile.toPath());
+            if (!indexExists && !configuredStoreCreationAllowed) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+            }
+
+            if (indexExists) {
+                validateFolder(configuredFolder);
+                validateIndex(configuredFolder, configuredStoredRulesFile);
+                configuredStoredRules.reload();
+
+                Inspection inspection = inspect(configuredFolder, configuredStoredRules, configuredFileNames);
+                finishInitialization(configuredFolder, configuredStoredRulesFile, configuredStoredRules,
+                        configuredFileNames, configuredIntegrityMode, inspection, configuredStoreCreationAllowed,
+                        configuredStoreUpdateAllowed);
+            } else {
+                /*
+                 * A fail-mode rejection must not create an index. Therefore an absent
+                 * index is inspected first and created only after that inspection succeeds.
+                 */
+                validateExistingFolderIfAny(configuredFolder);
+                Inspection inspection = inspect(configuredFolder, configuredStoredRules, configuredFileNames);
+                if (configuredIntegrityMode == IntegrityMode.FAIL && inspection.hasProblems()) {
+                    throw integrityFailure(configuredFolder, inspection);
+                }
+
+                ensureFolder(configuredFolder);
+                createIndex(configuredFolder, configuredStoredRulesFile);
+                configuredStoredRules.reload();
+                finishInitialization(configuredFolder, configuredStoredRulesFile, configuredStoredRules,
+                        configuredFileNames, configuredIntegrityMode, inspection, configuredStoreCreationAllowed,
+                        configuredStoreUpdateAllowed);
+            }
+
+            storeCreationAllowed = configuredStoreCreationAllowed;
+            storeUpdateAllowed = configuredStoreUpdateAllowed;
+            storeFolder = configuredFolder;
+            storedRules = configuredStoredRules;
+            fileNameConfiguration = configuredFileNames;
+            integrityMode = configuredIntegrityMode;
+        }
+    }
