+    private void finishInitialization(File folder, File storedRulesFile, FileSyncedProperties rules,
+            FileNameConfiguration fileNames, IntegrityMode integrity, Inspection inspection,
+            boolean creationAllowed, boolean updateAllowed) {
+        if (integrity == IntegrityMode.FAIL) {
+            if (inspection.hasProblems()) {
+                throw integrityFailure(folder, inspection);
+            }
+        } else if (integrity == IntegrityMode.REPAIR) {
+            repair(folder, storedRulesFile, rules, inspection);
+        }
+    }
