+    private IntegrityMode parseIntegrity(Properties properties) {
+        String value = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT);
+        if (INTEGRITY_REPAIR.equals(value)) {
+            return IntegrityMode.REPAIR;
+        }
+        if (INTEGRITY_FAIL.equals(value)) {
+            return IntegrityMode.FAIL;
+        }
+        if (INTEGRITY_IGNORE.equals(value)) {
+            return IntegrityMode.IGNORE;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid value '%s' for %s; accepted values are repair, fail and ignore",
+                value, INTEGRITY_PROPERTY_NAME));
+    }
+
+    private FileNameConfiguration parseFileNames(Properties properties) {
+        if (hasConstructorStrategy) {
+            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Configuration %s cannot be used with a constructor-supplied %s",
+                        FILE_NAMES_PROPERTY_NAME, RuleViolationFileNameStrategy.class.getSimpleName()));
+            }
+            return FileNameConfiguration.custom(constructorStrategy);
+        }
+
+        String value = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT);
+        if (FILE_NAMES_DEFAULT.equals(value)) {
+            return FileNameConfiguration.random();
+        }
+        if ("description".equals(value)) {
+            return FileNameConfiguration.description();
+        }
+        return FileNameConfiguration.custom(instantiateStrategy(value));
+    }
+
+    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
+        try {
+            Class<?> strategyClass = Class.forName(className);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Configured %s=%s is not a %s", FILE_NAMES_PROPERTY_NAME, className,
+                        RuleViolationFileNameStrategy.class.getName()));
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException |
+                 IllegalAccessException | InvocationTargetException | ClassCastException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s=%s; it must be a %s with a public no-argument constructor",
+                    FILE_NAMES_PROPERTY_NAME, className, RuleViolationFileNameStrategy.class.getName()), e);
+        }
+    }
+
+    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(), FileSyncedProperties::new);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void validateExistingFolderIfAny(File folder) {
+        if (existsWithoutFollowingLinks(folder.toPath()) && !Files.isDirectory(folder.toPath())) {
+            throw new StoreInitializationFailedException(String.format("Store path is not a directory: %s", folder.getAbsolutePath()));
+        }
+    }
+
+    private void validateFolder(File folder) {
+        validateExistingFolderIfAny(folder);
+        if (!existsWithoutFollowingLinks(folder.toPath())) {
+            throw new StoreInitializationFailedException(String.format("Store folder does not exist: %s", folder.getAbsolutePath()));
+        }
+        try {
+            folder.toPath().toRealPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format("Cannot resolve store folder: %s", folder.getAbsolutePath()), e);
+        }
+    }
+
+    private void validateIndex(File folder, File index) {
+        if (!Files.isRegularFile(index.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "The index must be a regular file directly in the store folder: %s", index.getAbsolutePath()));
+        }
+        try {
+            Path folderReal = folder.toPath().toRealPath();
+            Path indexParentReal = index.toPath().getParent().toRealPath();
+            if (!folderReal.equals(indexParentReal)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "The index must be a regular file directly in the store folder: %s", index.getAbsolutePath()));
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "The index must be a regular file directly in the store folder: %s", index.getAbsolutePath()), e);
+        }
+    }
+
+    private void ensureFolder(File folder) {
+        if (!folder.mkdirs() && !folder.isDirectory()) {
+            throw new StoreInitializationFailedException(String.format("Cannot create store folder: %s", folder.getAbsolutePath()));
+        }
+        validateFolder(folder);
+    }
+
+    private void createIndex(File folder, File index) {
+        try {
+            Files.createFile(index.toPath());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format("Cannot create rule store at %s", index.getAbsolutePath()), e);
+        }
+        validateIndex(folder, index);
