+
+    private static boolean existsWithoutFollowingLinks(Path path) {
+        return Files.exists(path, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storedRules) {
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            String description = ensureUnixLineBreaks(rule.getDescription());
+            String existingFileName = storedRules.getProperty(description);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                forgetKnownRule(description, existingFileName);
+                return;
+            }
+
+            if (existingFileName != null) {
+                Path target = writableExistingTarget(existingFileName);
+                write(violations, target, false);
+                return;
+            }
+
+            String fileName = createNewFileName(description);
+            Path target = validateNewTarget(fileName);
+            write(violations, target, true);
+            storedRules.put(description, fileName);
+            try {
+                storedRules.syncFileSystem();
+            } catch (RuntimeException e) {
+                storedRules.reloadAfterFailedUpdate();
+                deleteIfSafe(target);
+                throw e;
+            }
+        }
+    }
+
+    private void forgetKnownRule(String description, String existingFileName) {
+        if (existingFileName == null) {
+            return;
+        }
+        EntryPath entryPath = resolveEntryPath(existingFileName);
+        if (entryPath.resolvedPath != null && isIndex(entryPath.resolvedPath)) {
+            throw new StoreUpdateFailedException("Refusing to delete the stored.rules index");
+        }
+        if (!isSharedByAnotherEntry(description, entryPath)) {
+            deleteEntryFile(entryPath);
+        }
+        storedRules.remove(description);
+        storedRules.syncFileSystem();
+    }
+
+    private boolean isSharedByAnotherEntry(String description, EntryPath entryPath) {
+        for (Map.Entry<String, String> other : storedRules.entries().entrySet()) {
+            if (description.equals(other.getKey())) {
+                continue;
+            }
+            if (entryPath.recordedName.equals(other.getValue())) {
+                return true;
+            }
+            EntryPath otherPath = resolveEntryPath(other.getValue());
+            if (entryPath.resolvedPath != null && otherPath.resolvedPath != null && sameFile(entryPath.resolvedPath, otherPath.resolvedPath)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private void deleteEntryFile(EntryPath entryPath) {
+        if (entryPath.resolvedPath == null || !entryPath.isSafeDirectEntry || isIndex(entryPath.resolvedPath)) {
+            return;
+        }
+        try {
+            Files.deleteIfExists(entryPath.resolvedPath);
+            if (!entryPath.recordedPath.equals(entryPath.resolvedPath)) {
+                Files.deleteIfExists(entryPath.recordedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String createNewFileName(String description) {
+        String result = fileNameConfiguration.create(description);
+        ensureNamePresent(result);
+        return result;
+    }
+
+    private Path validateNewTarget(String fileName) {
+        Path target = directChild(fileName);
+        if (target == null || STORED_RULES_FILE_NAME.equals(fileName) || existsWithoutFollowingLinks(target)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to overwrite an existing or unsafe store file '%s'", fileName));
+        }
+        for (String recordedFileName : storedRules.values()) {
+            if (fileName.equals(recordedFileName)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write a file already recorded by another entry: '%s'", fileName));
+            }
+        }
+        return target;
+    }
+
+    private Path writableExistingTarget(String fileName) {
+        EntryPath entryPath = resolveEntryPath(fileName);
+        if (STORED_RULES_FILE_NAME.equals(fileName) || !entryPath.isSafeDirectEntry ||
+                (entryPath.resolvedPath != null && isIndex(entryPath.resolvedPath))) {
+            throw new StoreUpdateFailedException(String.format("Refusing to overwrite unsafe store file '%s'", fileName));
+        }
+        if (entryPath.resolvedPath != null) {
+            return entryPath.resolvedPath;
+        }
+        Path direct = directChild(fileName);
+        if (direct == null || existsWithoutFollowingLinks(direct)) {
+            throw new StoreUpdateFailedException(String.format("Cannot safely write store file '%s'", fileName));
+        }
+        return direct;
+    }
+
+    private Path directChild(String fileName) {
+        if (fileName == null || fileName.length() == 0) {
+            return null;
+        }
+        Path folderPath = storeFolder.toPath().toAbsolutePath().normalize();
+        Path raw = folderPath.resolve(fileName);
+        if (raw.isAbsolute() && !fileName.startsWith(folderPath.toString())) {
+            return null;
+        }
+        if (raw.getParent() == null || !raw.getParent().equals(folderPath)) {
+            return null;
+        }
+        return raw;
+    }
+
+    private void write(List<String> violations, Path target, boolean createNew) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        byte[] contents = builder.toString().getBytes(UTF_8);
+        try {
+            OpenOption[] options = createNew
+                    ? new OpenOption[]{StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE}
+                    : new OpenOption[]{StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE};
+            try (OutputStream outputStream = Files.newOutputStream(target, options)) {
+                outputStream.write(contents);
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void deleteIfSafe(Path target) {
+        try {
+            if (target != null && directChild(target.getFileName().toString()) != null) {
+                Files.deleteIfExists(target);
+            }
+        } catch (IOException ignored) {
+            log.debug("Could not remove an unindexed store file {} after a failed index update", target);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storedRules) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(resolveEntryPath(ruleDetailsFileName).resolvedPath);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(Path file) {
+        if (file == null) {
+            throw new StoreReadException(new IOException("Referenced violation file does not exist"));
+        }
+        String violationsText = readStoreFile(file);
+        String normalized = violationsText.replace("\r\n", "\n").replace('\r', '\n');
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(normalized)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(Path file) {
+        try {
+            return new String(toByteArray(file.toFile()), UTF_8);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private EntryPath resolveEntryPath(String fileName) {
+        Path folderPath = storeFolder.toPath().toAbsolutePath().normalize();
+        Path recordedPath = folderPath.resolve(fileName == null ? "" : fileName);
+        if (!existsWithoutFollowingLinks(recordedPath)) {
+            return new EntryPath(fileName, recordedPath, null, false);
+        }
+        try {
+            Path resolvedPath = recordedPath.toRealPath();
+            Path folderReal = folderPath.toRealPath();
+            boolean regularDirect = Files.isRegularFile(resolvedPath, LinkOption.NOFOLLOW_LINKS)
+                    && folderReal.equals(resolvedPath.getParent());
+            return new EntryPath(fileName, recordedPath, regularDirect ? resolvedPath : null,
+                    regularDirect && isDirectRecordedPath(recordedPath));
+        } catch (IOException e) {
+            return new EntryPath(fileName, recordedPath, null, false);
+        }
+    }
+
+    private boolean isDirectRecordedPath(Path path) {
+        Path folderPath = storeFolder.toPath().toAbsolutePath().normalize();
+        Path parent = path.toAbsolutePath().normalize().getParent();
+        return folderPath.equals(parent);
+    }
+
+    private boolean isIndex(Path path) {
+        try {
+            return path.toRealPath().equals(new File(storeFolder, STORED_RULES_FILE_NAME).toPath().toRealPath());
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private Inspection inspect(File folder, FileSyncedProperties rules, FileNameConfiguration fileNames) {
+        Path folderPath = folder.toPath().toAbsolutePath().normalize();
+        Path folderReal = null;
+        try {
+            if (Files.isDirectory(folderPath)) {
+                folderReal = folderPath.toRealPath();
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+
+        List<Entry> entries = new ArrayList<>();
+        for (Map.Entry<String, String> property : rules.entries().entrySet()) {
+            Entry entry = new Entry(property.getKey(), property.getValue());
+            entry.expectedName = fileNames.expectedName(entry.description);
+            entry.path = inspectEntryPath(folderPath, folderReal, entry.recordedName);
+            if (entry.path.resolvedPath != null && !isIndexPath(folder, entry.path.resolvedPath)) {
+                try {
+                    entry.resolved = readLines(entry.path.resolvedPath).isEmpty();
+                } catch (RuntimeException e) {
+                    entry.broken = true;
+                }
+            } else if (entry.path.resolvedPath != null) {
+                entry.reserved = true;
+            }
+            entry.broken = entry.path.resolvedPath == null;
+            entry.misplaced = entry.expectedName != null && !entry.expectedName.equals(entry.recordedName);
+            entries.add(entry);
+        }
+
+        markShared(entries);
+        markColliding(entries);
+        markOccupied(entries, folderPath, folderReal, folder);
+        List<String> unowned = findUnownedFiles(folder, folderPath);
+        return new Inspection(entries, unowned);
+    }
+
+    private EntryPath inspectEntryPath(Path folderPath, Path folderReal, String fileName) {
+        Path recordedPath = folderPath.resolve(fileName == null ? "" : fileName);
+        if (!existsWithoutFollowingLinks(recordedPath)) {
+            return new EntryPath(fileName, recordedPath, null, false);
+        }
+        try {
+            Path resolvedPath = recordedPath.toRealPath();
+            boolean regularDirect = Files.isRegularFile(resolvedPath, LinkOption.NOFOLLOW_LINKS)
+                    && folderReal != null && folderReal.equals(resolvedPath.getParent());
+            boolean safeRecordedPath = folderPath.equals(recordedPath.toAbsolutePath().normalize().getParent());
+            return new EntryPath(fileName, recordedPath, regularDirect ? resolvedPath : null,
+                    regularDirect && safeRecordedPath);
+        } catch (IOException e) {
+            return new EntryPath(fileName, recordedPath, null, false);
+        }
+    }
+
+    private boolean isIndexPath(File folder, Path path) {
+        try {
+            return path.equals(new File(folder, STORED_RULES_FILE_NAME).toPath().toRealPath());
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private void markShared(List<Entry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry left = entries.get(i);
+                Entry right = entries.get(j);
+                if (left.recordedName.equals(right.recordedName)
+                        || (left.path.resolvedPath != null && right.path.resolvedPath != null
+                        && sameFile(left.path.resolvedPath, right.path.resolvedPath))) {
+                    left.shared = true;
+                    right.shared = true;
+                }
+            }
+        }
+    }
+
+    private boolean sameFile(Path left, Path right) {
+        try {
+            return Files.isSameFile(left, right);
+        } catch (IOException e) {
+            return left.toAbsolutePath().normalize().equals(right.toAbsolutePath().normalize());
+        }
+    }
+
+    private void markColliding(List<Entry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry left = entries.get(i);
+                Entry right = entries.get(j);
+                if (left.expectedName != null && left.expectedName.equals(right.expectedName)) {
+                    left.colliding = true;
+                    right.colliding = true;
+                }
+            }
+        }
+    }
+
+    private void markOccupied(List<Entry> entries, Path folderPath, Path folderReal, File folder) {
+        for (Entry entry : entries) {
+            if (entry.expectedName == null) {
+                continue;
+            }
+            Path expected = folderPath.resolve(entry.expectedName);
+            boolean direct = !expected.isAbsolute() && expected.getParent() != null
+                    && expected.getParent().equals(folderPath);
+            if (!direct || STORED_RULES_FILE_NAME.equals(entry.expectedName)) {
+                entry.occupied = true;
+                continue;
+            }
+            for (Entry other : entries) {
+                if (other != entry && entry.expectedName.equals(other.recordedName)) {
+                    entry.occupied = true;
+                }
+            }
+            if (!entry.expectedName.equals(entry.recordedName) && existsWithoutFollowingLinks(expected)) {
+                entry.occupied = true;
+            }
+        }
+    }
+
+    private List<String> findUnownedFiles(File folder, Path folderPath) {
+        if (!Files.isDirectory(folderPath)) {
+            return Collections.emptyList();
+        }
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(folderPath)) {
+            for (Path file : files) {
+                if (STORED_RULES_FILE_NAME.equals(file.getFileName().toString())) {
+                    continue;
+                }
+                if (Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    result.add(file.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(result);
+        return result;
